mapper.select:
SELECT a.id, a.title, a.content, a.type, CASE a.type WHEN 1 THEN '系统公告' WHEN 2 THEN '日常公告' WHEN 3 THEN '维护通知' WHEN 4 THEN '活动公告' ELSE '未知' END as typeName, a.priority, CASE a.priority WHEN 1 THEN '普通' WHEN 2 THEN '重要' WHEN 3 THEN '紧急' ELSE '未知' END as priorityName, a.is_top, a.is_popup, a.publish_time, a.expire_time, a.status, CASE a.status WHEN 0 THEN '草稿' WHEN 1 THEN '已发布' WHEN 2 THEN '已下线' ELSE '未知' END as statusName, a.create_by, u.nickname as createByName, a.create_time, a.update_time FROM announcement a LEFT JOIN sys_user u ON a.create_by = u.id
AND a.type = #{type}
AND a.status = #{status}
AND a.title LIKE CONCAT('%', #{title}, '%')
ORDER BY a.is_top DESC, a.publish_time DESC, a.create_time DESC
